{"path": "/app/logkeep/rotate.py", "content": """"The rotate command (docs/rotate.md)."""

import gzip
import os
import re
from dataclasses import dataclass, field
from datetime import date, timedelta, timezone
from pathlib import Path

from logkeep import policy as policy_mod
from logkeep import state as state_mod
from logkeep import streams, timeparse
from logkeep.errors import DataError, Refused


@dataclass
class Archive:
    name: str  # name before the run ("" for the new archive)
    key: tuple  # position key: sorts newest first
    compressed: bool
    day: str = ""
    k: int = 1
    new: bool = False
    data: bytes | None = None  # content of the new archive
    final: str = ""
    compress_now: bool = False


@dataclass
class Plan:
    name: str
    what: str
    rotated: bool
    kept: list = field(default_factory=list)
    removed: list = field(default_factory=list)
    log_data: bytes | None = None
    entry: dict = field(default_factory=dict)


# ---------------------------------------------------------------- state


def _whole(v) -> bool:
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0


def validate_state(doc: dict, existing: set) -> None:
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        if "opened" in entry and timeparse.state_time(entry["opened"]) is None:
            raise DataError("state", f"state.json: {name}: opened is not a time")
        if "rotations" in entry and not _whole(entry["rotations"]):
            raise DataError("state", f"state.json: {name}: rotations is not a whole number")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"state.json: {name}: archives is not an object")
            for aname, t in arch.items():
                if timeparse.state_time(t) is None:
                    raise DataError("state", f"state.json: {name}: {aname}: not a time")


# ------------------------------------------------------------- archives


def _scan(logs: Path, name: str, naming: str) -> list:
    if not logs.is_dir():
        return []
    esc = re.escape(name)
    if naming == "numbered":
        rx = re.compile(esc + r"\.log\.([1-9][0-9]*)(\.gz)?")
    else:
        rx = re.compile(esc + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")
    found = []
    for p in sorted(logs.iterdir(), key=lambda q: q.name):
        m = rx.fullmatch(p.name)
        if not m or not p.is_file():
            continue
        if naming == "numbered":
            n = int(m.group(1))
            found.append(Archive(p.name, (n,), m.group(2) is not None))
        else:
            try:
                d = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            k = int(m.group(2)) if m.group(2) else 1
            found.append(Archive(p.name, (-d.toordinal(), -k), m.group(3) is not None, day=m.group(1), k=k))
    seen = set()
    for a in found:
        if a.key in seen:
            raise DataError("archives", f"{name}: two archives in the same place")
        seen.add(a.key)
    found.sort(key=lambda a: a.key)
    return found


def _first_line_time(path: Path):
    try:
        with path.open("rb") as f:
            line = f.readline(512)
    except OSError:
        return None
    line = line.rstrip(b"\r\n")
    token = line.split(b" ", 1)[0]
    try:
        return timeparse.iso(token.decode("utf-8"))
    except UnicodeDecodeError:
        return None


def _final_name(name: str, a: Archive, position: int, naming: str, gz: bool) -> str:
    suffix = ".gz" if gz else ""
    if naming == "numbered":
        return f"{name}.log.{position}{suffix}"
    k = f".{a.k}" if a.k > 1 else ""
    return f"{name}.log.{a.day}{k}{suffix}"


def _plan(ctx, name: str, cfg: dict, force: bool, doc: dict) -> Plan:
    logs = streams.logs_dir(ctx.data)
    naming = cfg["naming"]
    archives = _scan(logs, name, naming)
    active = streams.log_path(ctx.data, name)
    entry = doc["streams"].get(name, {})

    # section 3
    if not active.is_file():
        what, rotated = "no log", False
    else:
        size = active.stat().st_size
        if size == 0:
            what, rotated = "empty", False
        elif force:
            what, rotated = "forced", True
        elif cfg["max_size"] is not None and size >= cfg["max_size"]:
            what, rotated = "size", True
        else:
            what, rotated = "not due", False
            if cfg["max_age"] is not None:
                opened = timeparse.state_time(entry["opened"]) if "opened" in entry else _first_line_time(active)
                if opened is not None and ctx.now - opened >= cfg["max_age"]:
                    what, rotated = "age", True

    plan = Plan(name, what, rotated)

    # section 4
    if rotated:
        plan.log_data = active.read_bytes()
        if naming == "numbered":
            new = Archive("", (0,), False, new=True)
        else:
            tz = timezone(cfg["offset"])
            day = ctx.now.astimezone(tz).date().isoformat()
            used = {a.k for a in archives if a.day == day}
            k = 1
            if used:
                k = 2
                while k in used:
                    k += 1
            new = Archive("", (-date.fromisoformat(day).toordinal(), -k), False, day=day, k=k, new=True)
        new.data = plan.log_data
        archives.append(new)
        archives.sort(key=lambda a: a.key)

    # section 5
    times = {}
    arch_state = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
    for a in archives:
        if a.new:
            times[id(a)] = ctx.now
        elif a.name in arch_state:
            times[id(a)] = timeparse.state_time(arch_state[a.name])
    keep_days = cfg["keep_days"]
    remaining = []
    for pos, a in enumerate(archives, 1):
        drop = pos > cfg["keep"]
        if not drop and keep_days is not None and id(a) in times:
            drop = ctx.now - times[id(a)] >= timedelta(days=keep_days)
        if drop:
            plan.removed.append(a)
        else:
            remaining.append(a)

    # section 6
    for pos, a in enumerate(remaining, 1):
        a.compress_now = pos > cfg["compress_after"] and not a.compressed
        a.final = _final_name(name, a, pos, naming, a.compressed or a.compress_now)
        if a.compress_now and not a.new:
            a.data = (logs / a.name).read_bytes()
    plan.kept = remaining

    # section 7
    new_entry = {}
    if rotated:
        new_entry["opened"] = ctx.stamp
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_archives = {}
    for a in remaining:
        if a.new:
            new_archives[a.final] = ctx.stamp
        elif a.name in arch_state:
            new_archives[a.final] = arch_state[a.name]
    new_entry["archives"] = new_archives
    plan.entry = new_entry
    return plan


# ------------------------------------------------------------ execution


def _gz(data: bytes) -> bytes:
    return gzip.compress(data, mtime=0)


def _temp(logs: Path, i: int) -> Path:
    n = 0
    while True:
        p = logs / f".logkeep-tmp-{i}-{n}"
        if not p.exists():
            return p
        n += 1


def _execute(ctx, plan: Plan) -> None:
    logs = streams.logs_dir(ctx.data)
    for a in plan.removed:
        if not a.new:
            (logs / a.name).unlink()
    moves = []
    for i, a in enumerate(plan.kept):
        if a.new or a.final == a.name:
            continue
        tmp = _temp(logs, i)
        src = logs / a.name
        if a.compress_now:
            tmp.write_bytes(_gz(a.data))
            src.unlink()
        else:
            os.rename(src, tmp)
        moves.append((tmp, logs / a.final))
    for tmp, dst in moves:
        os.rename(tmp, dst)
    for a in plan.kept:
        if a.new:
            (logs / a.final).write_bytes(_gz(a.data) if a.compress_now else a.data)
            streams.log_path(ctx.data, plan.name).write_bytes(b"")


# --------------------------------------------------------------- command


def run(ctx, names: list, dry_run: bool, force: bool) -> list:
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    validate_state(doc, existing)
    targets = sorted(set(names)) if names else sorted(existing)
    for n in targets:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")
    plans = [_plan(ctx, n, pol.settings(n), force, doc) for n in targets]

    out = []
    rotated = removed = compressed = 0
    for p in plans:
        out.append(f"{p.name}: " + (f"rotate ({p.what})" if p.rotated else p.what))
        for a in p.kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.final}")
            compressed += a.compress_now
        for a in p.removed:
            out.append(f"  remove {a.name}")
        rotated += p.rotated
        removed += len(p.removed) - sum(a.new for a in p.removed)
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")

    if dry_run:
        out.append("dry run: nothing written")
        return out
    for p in plans:
        _execute(ctx, p)
    new_doc = dict(doc)
    new_streams = dict(doc["streams"])
    for p in plans:
        new_streams[p.name] = p.entry
    new_doc["streams"] = new_streams
    state_mod.save(ctx.state_path, new_doc)
    return out
"}

